import{_ as d,C as o,o as c,c as g,j as t,a as i,E as r,a2 as n}from"./chunks/framework.CAzL99r7.js";const S=JSON.parse('{"title":"Architecture Overview","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/index.md","filePath":"architecture/index.md"}'),p={name:"architecture/index.md"};function h(m,e,u,y,v,f){const a=o("ArchitectureFlow"),s=o("TelemetrySimulator"),l=o("BatterySequenceFlow");return c(),g("div",null,[e[0]||(e[0]=t("h1",{id:"architecture-overview",tabindex:"-1"},[i("Architecture Overview "),t("a",{class:"header-anchor",href:"#architecture-overview","aria-label":'Permalink to "Architecture Overview"'},"​")],-1)),e[1]||(e[1]=t("p",null,[i("The "),t("strong",null,"Veg Sahayyak SDK"),i(" is engineered around a clean, decoupled, and framework-agnostic architecture. This ensures high-accuracy telematics processing in background environments without imposing dependency injection frameworks (like Hilt or Koin) onto host applications.")],-1)),e[2]||(e[2]=t("hr",null,null,-1)),e[3]||(e[3]=t("h2",{id:"modular-architecture",tabindex:"-1"},[i("Modular Architecture "),t("a",{class:"header-anchor",href:"#modular-architecture","aria-label":'Permalink to "Modular Architecture"'},"​")],-1)),e[4]||(e[4]=t("p",null,"The SDK is strictly modularized into 5 components to enforce separation of concerns and enable flexible, lightweight B2B integration:",-1)),r(a),e[5]||(e[5]=n('<h3 id="module-responsibilities" tabindex="-1">Module Responsibilities <a class="header-anchor" href="#module-responsibilities" aria-label="Permalink to &quot;Module Responsibilities&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Module</th><th style="text-align:left;">Namespace</th><th style="text-align:left;">Role</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>speed-core</code></strong></td><td style="text-align:left;"><code>com.vegsahayyak.speedcore</code></td><td style="text-align:left;"><strong>Headless Engine</strong>: Location tracking, <code>TelematicsEngine</code> signal processing, Foreground Service, <code>SpeedColorScheme</code>, persistent preferences, and repository contracts. <strong>Crucially, this module is entirely headless and contains zero Jetpack Compose or UI dependencies.</strong></td></tr><tr><td style="text-align:left;"><strong><code>speed-ui</code></strong></td><td style="text-align:left;"><code>com.vegsahayyak.speedui</code></td><td style="text-align:left;"><strong>Jetpack Compose UI</strong>: Production-ready, animated <code>SpeedGauge</code> canvas component, <code>HudDisplay</code> night windshield projection, and <code>SpeedUiColorScheme</code>. All UI rendering is fully delegated here.</td></tr><tr><td style="text-align:left;"><strong><code>speed-overlay</code></strong></td><td style="text-align:left;"><code>com.vegsahayyak.speedoverlay</code></td><td style="text-align:left;"><strong>Floating PiP Overlay</strong>: Lightweight floating Picture-in-Picture window for persistent speed display over third-party navigation apps.</td></tr><tr><td style="text-align:left;"><strong><code>speed-autostart</code></strong></td><td style="text-align:left;"><code>com.vegsahayyak.speedautostart</code></td><td style="text-align:left;"><strong>Zero-Touch Autostart</strong>: Seamless background trip detection via Google Play Activity Recognition (<code>IN_VEHICLE</code> transitions).</td></tr><tr><td style="text-align:left;"><strong><code>speed-bom</code></strong></td><td style="text-align:left;"><code>com.vegsahayyak.speedbom</code></td><td style="text-align:left;"><strong>Bill of Materials</strong>: Aligns module versioning (v2.2.2) so clients never encounter runtime ABI mismatches.</td></tr></tbody></table><hr><h2 id="native-security-hardening-native-engine" tabindex="-1">Native Security &amp; Hardening (Native Engine) <a class="header-anchor" href="#native-security-hardening-native-engine" aria-label="Permalink to &quot;Native Security &amp; Hardening (Native Engine)&quot;">​</a></h2><p>In <strong>v2.2.2</strong>, core telematics signal processing and license validation routines are compiled directly into the SDK&#39;s <strong>Native C++ Engine</strong>. This provides defense-in-depth protection for commercial enterprise integrations:</p><ul><li><strong>Runtime Integrity Checks</strong>: The native engine inspects <code>/proc/self/maps</code> at runtime to detect dynamic hooking frameworks (such as Frida or Xposed) and memory tampering.</li><li><strong>Time-Travel &amp; GPS Spoofing Defense</strong>: Implements high-water mark timestamp validation to reject manipulated, replayed, or reversed GPS fix packets.</li><li><strong>Compiled Signal Processing</strong>: Velocity smoothing (EMA) and dynamic boundary math are computed directly in native C++ with hidden symbol visibility (<code>-fvisibility=hidden</code>), cryptographically coupled to active license memory state.</li><li><strong>Minimal Binary Footprint</strong>: Fully stripped to less than 300KB per ABI (<code>arm64-v8a</code>, <code>armeabi-v7a</code>, <code>x86</code>, <code>x86_64</code>), preserving the SDK&#39;s lightweight footprint with zero impact on host application APK size.</li></ul><hr><h2 id="two-tier-enterprise-licensing-privacy-first-telemetry" tabindex="-1">Two-Tier Enterprise Licensing &amp; Privacy-First Telemetry <a class="header-anchor" href="#two-tier-enterprise-licensing-privacy-first-telemetry" aria-label="Permalink to &quot;Two-Tier Enterprise Licensing &amp; Privacy-First Telemetry&quot;">​</a></h2><p>The SDK operates on a dual-tier, offline-first <strong>Commercial Enterprise License</strong> and <strong>Privacy-First Telemetry</strong> model, eliminating runtime third-party authentication servers or tracking dependencies:</p><h3 id="_1-two-tier-licensing-model" tabindex="-1">1. Two-Tier Licensing Model <a class="header-anchor" href="#_1-two-tier-licensing-model" aria-label="Permalink to &quot;1. Two-Tier Licensing Model&quot;">​</a></h3><ol><li><strong>Tier 1 (Application Layer / Cryptographic Claims)</strong>: On-device offline RSA-2048 JWT verification in Kotlin (<code>LicenseManager</code>) parses signed tokens encoding authorized module entitlements (such as <code>:speed-ui</code>, <code>:speed-overlay</code>, <code>:speed-autostart</code>) and expiration bounds.</li><li><strong>Tier 2 (Native Hardening &amp; Math Coupling)</strong>: All velocity calculations and boundary logic inside the native engine are cryptographically coupled to the valid license key. Fleets and logistics vehicles operate uninterrupted in remote, tunnel, or off-grid environments without periodic server ping requirements.</li></ol><h3 id="_2-privacy-first-telemetry-policy" tabindex="-1">2. Privacy-First Telemetry Policy <a class="header-anchor" href="#_2-privacy-first-telemetry-policy" aria-label="Permalink to &quot;2. Privacy-First Telemetry Policy&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Privacy-First Telemetry Guarantee</p><p>Core speed tracking operates <strong>100% offline</strong>. For tiered commercial licenses, a lightweight periodic heartbeat transmits session duration and total distance traveled for billing reconciliation. <strong>Zero GPS coordinates, routes, or location points are ever logged, cached, or transmitted to any remote server or third-party cloud.</strong></p></div><ul><li><strong>100% On-Device Velocity Processing</strong>: All speed calculations, smoothing, and boundary alarms occur locally in memory.</li><li><strong>Aggregated Heartbeat for Tiered Licenses</strong>: For commercial tiered licenses, a lightweight periodic heartbeat (<code>TelemetryJobService</code>) reports only aggregate session metrics: session duration (<code>duration_ms</code>), cumulative distance traveled (<code>distance_meters</code>), and client ID for billing reconciliation.</li><li><strong>Zero Location Data Transmitted</strong>: <strong>Zero GPS coordinates, waypoints, routes, or location tracks are ever recorded, cached, or transmitted to any remote server or third-party cloud.</strong> Enterprises retain full data sovereignty and effortless compliance with global privacy regulations (GDPR, California CCPA, India DPDP).</li><li><strong>Zero Overhead for Unlimited Tiers</strong>: Unlimited enterprise license holders bypass telemetry logging and synchronization completely.</li></ul><hr><h2 id="signal-processing-telematics-engine" tabindex="-1">Signal Processing &amp; Telematics Engine <a class="header-anchor" href="#signal-processing-telematics-engine" aria-label="Permalink to &quot;Signal Processing &amp; Telematics Engine&quot;">​</a></h2><p>GPS hardware sensors on mobile devices frequently produce velocity noise spikes, multipath signal reflections, and intermittent signal drift (especially in urban canyons or under bridges). The <code>TelematicsEngine</code> in <code>speed-core</code> applies a multi-stage mathematical pipeline before emitting speed updates.</p>',17)),r(s),e[6]||(e[6]=n('<h3 id="_1-accuracy-confidence-gating" tabindex="-1">1. Accuracy Confidence Gating <a class="header-anchor" href="#_1-accuracy-confidence-gating" aria-label="Permalink to &quot;1. Accuracy Confidence Gating&quot;">​</a></h3><p>Raw GPS fixes with an estimated horizontal accuracy greater than our <strong>proprietary internal threshold</strong> (20.0 meters) or missing speed precision are discarded:</p><div class="info custom-block"><p class="custom-block-title">Gating Rule</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Accept GPS Fix IF: horizontalAccuracy &lt;= CONFIDENCE_THRESHOLD (2σ confidence)</span></span></code></pre></div></div><p>When a reading is rejected, the engine emits <code>SpeedData.LowAccuracy</code>, preventing erratic spikes while preserving the last valid smoothed speed.</p><hr><h3 id="_2-native-exponential-moving-average-ema-smoothing" tabindex="-1">2. Native Exponential Moving Average (EMA) Smoothing <a class="header-anchor" href="#_2-native-exponential-moving-average-ema-smoothing" aria-label="Permalink to &quot;2. Native Exponential Moving Average (EMA) Smoothing&quot;">​</a></h3><p>To eliminate abrupt needle shaking while retaining immediate responsiveness to actual vehicle acceleration, the engine applies an <strong>Exponential Moving Average</strong> executed directly within the native C++ engine:</p><div class="info custom-block"><p class="custom-block-title">Mathematical Smoothing Formula</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SmoothedVelocity[t] = α · RawVelocity[t] + (1 - α) · SmoothedVelocity[t - 1]</span></span></code></pre></div><ul><li><strong><code>S_t</code></strong>: Smoothed speed at timestamp <em>t</em> (in meters/second).</li><li><strong><code>Y_t</code></strong>: Raw velocity reading from the GPS provider.</li><li><strong><code>S_{t-1}</code></strong>: Previous smoothed speed state.</li><li><strong><code>α</code></strong>: Proprietary calibrated smoothing coefficient, executed securely inside the native engine with immediate snap-to-speed on standstill or trip start.</li></ul></div><hr><h3 id="_3-dynamic-speed-limit-thresholding-safety-logic" tabindex="-1">3. Dynamic Speed Limit Thresholding &amp; Safety Logic <a class="header-anchor" href="#_3-dynamic-speed-limit-thresholding-safety-logic" aria-label="Permalink to &quot;3. Dynamic Speed Limit Thresholding &amp; Safety Logic&quot;">​</a></h3><p>Speed limits are automatically derived from the active <strong><code>DrivingProfile</code></strong> (e.g. <code>CarHighway</code>, <code>SchoolZone</code>, <code>EScooter</code>):</p><ul><li><strong>Over-Speed Alert</strong>: Triggers deterministically when smoothed speed exceeds the profile limit (<code>smoothedSpeed &gt; warningThresholdMps</code>), immediately setting <code>isOverLimit = true</code>.</li><li><strong>Under-Speed Corridor Warning</strong>: When a minimum speed corridor is configured, triggers when driving speed drops below the corridor floor (<code>isUnderLimit = true</code>).</li><li><strong>Stationary Suppression</strong>: To avoid annoying false under-speed warnings when starting a vehicle, waiting at traffic lights, or navigating speed bumps, under-speed alerts are automatically silenced during stop-and-go conditions.</li><li><strong>Clean Deterministic Boundaries</strong>: Pre-filtering raw sensor noise via native EMA smoothing removes the need for artificial hysteresis dismissal lags (which can cause alarms to hang after a driver has decelerated and unfairly penalize driver safety scores).</li></ul><hr><h2 id="foreground-service-battery-optimization" tabindex="-1">Foreground Service &amp; Battery Optimization <a class="header-anchor" href="#foreground-service-battery-optimization" aria-label="Permalink to &quot;Foreground Service &amp; Battery Optimization&quot;">​</a></h2><p>Continuous GPS monitoring can drain mobile battery rapidly. The SDK provides advanced power-conservation strategies:</p>',15)),r(l),e[7]||(e[7]=n('<ol><li><strong><code>AutoStartManager</code> (<code>:speed-autostart</code>)</strong>: This is the new recommended strategy for battery optimization. By utilizing Google Play Services <code>IN_VEHICLE</code> transitions, it detects when a trip starts or stops using the low-power sensor hub, bypassing OEM background killers without relying on continuous GPS polling.</li><li><strong><code>ScreenStateWatcher</code></strong>: Dynamically observes display state. If the host application configures <code>updateWhileScreenOff = false</code>, the GPS hardware is immediately turned off when the screen sleeps, reducing power consumption by up to <strong>68%</strong>.</li><li><strong>Dynamic Status Bar Icons</strong>: Speed is rendered directly into the system status bar as a vector numeric drawable, allowing drivers to monitor speed without keeping the screen active.</li></ol><hr><p><strong>Next Step:</strong> Explore the <a href="/pr-preview/pr-60/guide/">Core Integration Guide</a> to initialize the SDK and collect live telematics streams.</p>',3))])}const w=d(p,[["render",h]]);export{S as __pageData,w as default};
